<?php require 'faculty_bootstrap.php';$title='Teaching Schedule';$fid=(int)$_SESSION['user']['id'];$q=$pdo->prepare("SELECT o.*,s.code,s.name,s.units,COUNT(DISTINCT CASE WHEN e.status='approved' THEN e.student_id END) student_count FROM subject_offerings o JOIN subjects s ON s.id=o.subject_id LEFT JOIN enrollments e ON e.offering_id=o.id WHERE o.faculty_id=? GROUP BY o.id ORDER BY FIELD(o.day_name,'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'),o.start_time,s.code");$q->execute([$fid]);$rows=$q->fetchAll();require 'header.php';
?><section class="section"><div class="section-intro"><div><span class="eyebrow">WEEKLY TIMETABLE</span><h2>Teaching Schedule</h2><p class="muted">Your assigned teaching schedule for the current offerings.</p></div><a class="btn" href="faculty_classes.php">My Classes</a></div><div class="calendar-wrap"><div class="calendar faculty-calendar faculty-timetable"><div class="cal-corner">Time</div><?php foreach(["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"] as $d):?><div class="cal-day-head"><?=e(substr($d,0,3))?></div><?php endforeach;?><?php for($h=7;$h<=19;$h++):?><div class="cal-time"><?=date('g A',mktime($h,0))?></div><div class="cal-cell"></div><div class="cal-cell"></div><div class="cal-cell"></div><div class="cal-cell"></div><div class="cal-cell"></div><div class="cal-cell"></div><?php endfor;?><?php $dayCols=['Monday'=>2,'Tuesday'=>3,'Wednesday'=>4,'Thursday'=>5,'Friday'=>6,'Saturday'=>7]; foreach($rows as $r): $st=strtotime($r['start_time']); $en=strtotime($r['end_time']); $startMin=((int)date('G',$st)-7)*60+(int)date('i',$st); $endMin=((int)date('G',$en)-7)*60+(int)date('i',$en); $rowStart=2+intdiv(max(0,$startMin),60); $rowEnd=2+max($rowStart-1,intdiv(max(1,$endMin),60)); if($endMin%60!==0){$rowEnd++;} if($rowEnd<=$rowStart){$rowEnd=$rowStart+1;} ?><a class="class-block timetable-block" style="grid-column:<?=$dayCols[$r['day_name']]?>;grid-row:<?=$rowStart?> / <?=$rowEnd?>" href="faculty_classes.php?offering=<?=e($r['id'])?>"><b><?=e($r['code'])?></b><span><?=e($r['section'])?></span><small><?=date('g:i A',$st)?>–<?=date('g:i A',$en)?></small><em><?=e($r['room'])?></em></a><?php endforeach;?></div></div></section><section class="section"><div class="card-head"><h2>Schedule Details</h2><span class="muted"><?=count($rows)?> assigned offerings</span></div><div class="table-scroll"><table class="table"><tr><th>Subject</th><th>Day</th><th>Time</th><th>Section</th><th>Room</th><th>Students</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['code'])?></b><br><?=e($r['name'])?></td><td><?=e($r['day_name'])?></td><td><?=date('g:i A',strtotime($r['start_time']))?>–<?=date('g:i A',strtotime($r['end_time']))?></td><td><?=e($r['section'])?></td><td><?=e($r['room'])?></td><td><?=e($r['student_count'])?></td></tr><?php endforeach;?></table></div></section><?php require 'footer.php';?>
